document.querySelectorAll('[data-solution]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-solution]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelectorAll('.solution-card').forEach(card=>{card.hidden=button.dataset.solution!=='all'&&card.dataset.group!==button.dataset.solution});}));
let currentScene=0;function showScene(index){if(currentScene===index)return;currentScene=index;document.querySelectorAll('[data-scene]').forEach(el=>{el.hidden=Number(el.dataset.scene)!==index;el.classList.toggle('is-entering',!el.hidden)});document.querySelectorAll('[data-chapter]').forEach(el=>el.classList.toggle('is-current',Number(el.dataset.chapter)===index));document.querySelectorAll('[data-show-scene]').forEach(el=>el.setAttribute('aria-pressed',Number(el.dataset.showScene)===index));}
document.querySelectorAll('[data-show-scene]').forEach(b=>b.addEventListener('click',()=>{showScene(Number(b.dataset.showScene));if(innerWidth<761)document.querySelector('.day-story-visual').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})}));
if('IntersectionObserver'in window){const chapterObserver=new IntersectionObserver(entries=>{if(innerWidth<761)return;const visible=entries.filter(e=>e.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio);if(visible[0])showScene(Number(visible[0].target.dataset.chapter))},{rootMargin:'-25% 0px -35% 0px',threshold:[0,.3,.6,1]});document.querySelectorAll('[data-chapter]').forEach(el=>chapterObserver.observe(el));}
